import * as api from "@/lib/api";
import { ApiError } from "@/lib/api-error";
import { useNetworkStatus } from "@/offline/network";
import { requestSync } from "@/offline/syncScheduler";
import {
  createLocalNote,
  updateLocalNote,
  deleteLocalNote,
  getLocalNotes,
  getLocalNote,
  type NoteInput,
} from "@/offline/localNoteApi";
