  constructor() {
    super("zenotes-offline");
    this.version(1).stores({
      notes: "id, syncStatus, updatedAt",
      images: "id, noteId, syncStatus",
      syncQueue: "++id, type, entityId, createdAt",
    });
  }
}

export const db = new ZenotesDb();

