async function withRetry(fn, label, max = 5) {
  let lastErr;
  for (let i = 1; i <= max; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (!isRetryableNetworkError(e) || i === max) throw e;
      const wait = Math.min(5000, 300 * 2 ** (i - 1));
      console.warn(`  ${label} 网络异常，${wait}ms 后重试 (${i}/${max})`);
      await sleep(wait);
    }
  }
  throw lastErr;
}

