export type NoteInput = Partial<Omit<LocalNote, "id" | "syncStatus" | "isDeleted" | "createdAt" | "updatedAt">>;

export function nowIso(): string {
  return new Date().toISOString();
}

export async function createLocalNote(input: NoteInput = {}) {
  const ts = nowIso();
  const isPinned = input.pinned ?? false;

  // Find minimum position among notes in the same pinned state so new note is always ranked first (minPos - 1)
  const existing = await db.notes
    .filter((n) => !n.isDeleted && Boolean(n.pinned) === isPinned)
    .toArray();
  const minPos = existing.reduce(
    (min, n) => Math.min(min, Number.isFinite(n.position) ? n.position : 0),
    0,
  );
  const position = minPos - 1;

  const note: LocalNote = {
    id: generateId(),
    content: "",
    title: null,
    color: "white",
    tags: [],
    pinned: isPinned,
    position,
    ...input,
    createdAt: ts,
    updatedAt: ts,
    syncStatus: "pending",
    isDeleted: false,
  };
  await db.notes.add(note);
  await db.syncQueue.add({
    type: "CREATE_NOTE",
    entityId: note.id,
    payload: {
      ...input,
      id: note.id,
      position: note.position,
    },
    retries: 0,
    createdAt: Date.now(),
  });
  return note;
}

