import type { Note } from "@/types/note";
import * as api from "@/lib/api";
import { db } from "./db";
import { processSyncQueue } from "./syncEngine";

/** Merge server notes into IndexedDB without resurrecting locally deleted tombstones. */
export async function mergeServerNotesIntoLocal(notes: Note[]) {
  const pendingCreates = new Set(
    (await db.syncQueue.where("type").equals("CREATE_NOTE").toArray()).map((op) => op.entityId),
  );

  await db.transaction("rw", db.notes, async () => {
    for (const note of notes) {
      if (pendingCreates.has(note.id)) continue;

      const exists = await db.notes.get(note.id);
      if (exists?.isDeleted) continue;
      if (exists) {
        if (exists.syncStatus === "synced") {
          await db.notes.update(note.id, {
            ...note,
            title: note.title ?? null,
            tags: note.tags ?? [],
            syncStatus: "synced",
            isDeleted: false,
          } as any);
        }
        continue;
      }

      try {
        await db.notes.add({
          ...note,
          title: note.title ?? null,
          tags: note.tags ?? [],
          syncStatus: "synced",
          isDeleted: false,
        } as any);
      } catch (err) {
        // Race: another tab or sync just wrote this id — update instead of crashing.
        if (err instanceof Error && err.name === "ConstraintError") {
          await db.notes.update(note.id, {
            ...note,
            title: note.title ?? null,
            tags: note.tags ?? [],
            syncStatus: "synced",
            isDeleted: false,
          } as any);
        } else {
          throw err;
        }
      }
    }

    // Purge local synced notes that no longer exist on the server (e.g. wiped/deleted on server)
    const serverIds = new Set(notes.map((n) => n.id));
    const allLocal = await db.notes.filter((n) => !n.isDeleted && n.syncStatus === "synced").toArray();
    for (const local of allLocal) {
      if (!serverIds.has(local.id) && !pendingCreates.has(local.id)) {
        await db.notes.delete(local.id);
      }
    }
  });
}

const SEED_PAGE_SIZE = 50;

/** Push local changes first, then merge server state (avoids seed/sync races). */
export async function pullServerNotes() {
  await processSyncQueue();
  const notes: Note[] = [];
  let page = 1;
  let total = 0;
  let totalPages = 1;
  do {
    const data = await api.fetchNotes(page, SEED_PAGE_SIZE);
    notes.push(...(data.notes ?? []));
    total = data.pagination?.total ?? notes.length;
    totalPages = Math.max(1, data.pagination?.totalPages ?? 1);
    if ((data.notes ?? []).length === 0) break;
    page += 1;
  } while (page <= totalPages);

  await mergeServerNotesIntoLocal(notes);
  return {
    notes,
    pagination: { page: 1, pageSize: notes.length, total, totalPages: 1 },
  };
}

