export async function uploadNoteMedia(noteId: string, file: File): Promise<{ id: string }> {
  const t = (file.type || "").trim().toLowerCase();
  /** 空类型时误标成 png 会导致服务端误判；交给 Worker 用魔数识别 */
  const headers: HeadersInit =
