        >
          {parseNoteContentToNodes(raw, note.id, "card")}
        </div>
        ) : (
          <p className="text-xs text-muted-foreground/50">无正文</p>
        )}

        {note.tags?.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-2">
            {note.tags.slice(0, 4).map((t) => (
              <Badge
                key={t}
                variant="secondary"
                onClick={(e) => {
                  e.stopPropagation();
                  onTagClick?.(t);
                }}
